    const xl = x & MASK;
    const yl = y & MASK;
    const xh = (x - xl) / BASE;
    const yh = (y - yl) / BASE;

    let result = Math.imul(xh, yh) % MOD;
    result = (result * BASE + Math.imul(xh, yl) + Math.imul(xl, yh)) % MOD;
    result = (result * BASE + Math.imul(xl, yl)) % MOD;
    return result;
